   408→/**
   409→ * Calculate regional population decline for an organization
   410→ * 
   411→ * Organizations care about their LOCAL market, not global population.
   412→ * - US-based orgs (OpenAI, Google, Meta): Care about North America population
   413→ * - EU-based orgs: Care about Europe population  
   414→ * - China-based orgs (Alibaba, Baidu): Care about East Asia population
   415→ * 
   416→ * Determines market region from data center locations.
   417→ */
   418→function calculateRegionalPopulationDecline(org: Organization, state: GameState): number {
   419→  // Determine org's primary market from data center locations
   420→  const orgDataCenters = state.computeInfrastructure.dataCenters.filter(dc =>
   421→    org.ownedDataCenters.includes(dc.id)
   422→  );
   423→  
   424→  // Count data centers by region
   425→  const regionCounts = new Map<string, number>();
   426→  for (const dc of orgDataCenters) {
   427→    const region = dc.region || 'US'; // Default to US if not specified
   428→    regionCounts.set(region, (regionCounts.get(region) || 0) + 1);
   429→  }
   430→  
   431→  // Find primary region (most data centers)
   432→  let primaryRegion = 'US'; // Default
   433→  let maxCount = 0;
   434→  for (const [region, count] of regionCounts) {
   435→    if (count > maxCount) {
   436→      primaryRegion = region;
   437→      maxCount = count;
   438→    }
   439→  }
   440→  
   441→  // Map region to relevant countries
   442→  const relevantCountries = getCountriesInRegion(primaryRegion);
   443→  
   444→  // Calculate population decline in those countries
   445→  if (!state.countryPopulationSystem) {
   446→    // Fallback to global if country tracking not available
   447→    const currentPop = state.humanPopulationSystem.population;
   448→    const initialPop = 8.0;
   449→    return 1 - (currentPop / initialPop);
   450→  }
   451→  
   452→  let totalBaseline = 0;
   453→  let totalCurrent = 0;
   454→  
   455→  for (const countryName of relevantCountries) {
   456→    const country = state.countryPopulationSystem.countries[countryName];
   457→    if (country) {
   458→      totalBaseline += country.baselinePopulation;
   459→      totalCurrent += country.population;
   460→    }
   461→  }
   462→  
   463→  if (totalBaseline === 0) {
   464→    // Fallback to global
   465→    const currentPop = state.humanPopulationSystem.population;
   466→    const initialPop = 8.0;
   467→    return 1 - (currentPop / initialPop);
   468→  }
   469→  
   470→  return 1 - (totalCurrent / totalBaseline);
   471→}
   472→
   473→/**
   474→ * Get countries in a region for market analysis
   475→ */
   476→function getCountriesInRegion(region: string): import('@/types/countryPopulations').CountryName[] {
   477→  switch (region.toLowerCase()) {
   478→    case 'us':
   479→    case 'united states':
   480→    case 'north america':
   481→      return ['United States', 'Canada'];
   482→    
   483→    case 'eu':
   484→    case 'europe':
   485→      return ['United Kingdom', 'France', 'Germany'];
   486→    
   487→    case 'china':
   488→    case 'east asia':
   489→      return ['China', 'Japan'];
   490→    
   491→    case 'india':
   492→    case 'south asia':
   493→      return ['India', 'Bangladesh', 'Pakistan'];
   494→    
   495→    case 'distributed':
   496→    case 'global':
   497→      // Distributed orgs care about top 5 economies
   498→      return ['United States', 'China', 'India', 'Japan', 'Germany'];
   499→    
   500→    default:
   501→      // Unknown region, assume US
   502→      return ['United States', 'Canada'];
   503→  }
   504→}
   505→
   506→/**
   507→ * Calculate revenue from deployed AI models
   508→ * 
   509→ * IMPORTANT: Open-weight models generate NO revenue (can't charge for free weights)
   510→ * Instead, organizations earn from selling unused compute capacity
   511→ * 
   512→ * NEW (Oct 13, 2025): Revenue penalized during population collapse
   513→ * - No customers when people are dying
   514→ * - Infrastructure fails during cascading crises
   515→ */
   516→export function calculateAIRevenue(org: Organization, state: GameState): number {
   517→  const { calculateTotalCapabilityFromProfile } = require('./capabilities');
   518→  
   519→  // ONLY closed/proprietary models generate revenue
   520→  const revenueGeneratingModels = state.aiAgents.filter(ai =>
   521→    org.ownedAIModels.includes(ai.id) &&
   522→    ai.lifecycleState === 'deployed_closed'
   523→    // deployed_open is EXCLUDED - open weights can't charge
   524→  );
   525→  
   526→  if (revenueGeneratingModels.length === 0) return 0;
   527→  
   528→  // Revenue scales with CAPABILITY (better models = more revenue)
   529→  // Use trueCapability since that's what the model actually delivers
   530→  const revenues = revenueGeneratingModels.map(ai => {
   531→    const capability = calculateTotalCapabilityFromProfile(ai.trueCapability);
   532→    const marketMultiplier = 1.0 + (state.globalMetrics.economicTransitionStage * 0.5);
   533→    const baseRevenuePerCapability = 25; // $25M per capability point per month
   534→    
   535→    return baseRevenuePerCapability * capability * marketMultiplier;
   536→  });
   537→  
   538→  const totalModelRevenue = revenues.reduce((sum, r) => sum + r, 0);
   539→  
   540→  // Economies of scale bonus (more models = better market presence)
   541→  const scaleBonus = 1.0 + Math.log(1 + revenueGeneratingModels.length) * 0.2;
   542→  
   543→  let baseRevenue = totalModelRevenue * scaleBonus;
   544→  
   545→  // === NEW: CRISIS REVENUE PENALTIES (Oct 13, 2025) ===
   546→  // Organizations can't make money when customers are dying and infrastructure is failing
   547→  
   548→  // 1. POPULATION COLLAPSE PENALTY
   549→  // When people die, there are fewer customers
   550→  // NEW (Oct 13, 2025): Use REGIONAL population, not global!
   551→  // Google cares about US/EU population, Alibaba cares about Asia
   552→  const regionalPopulationDecline = calculateRegionalPopulationDecline(org, state);
   553→  
   554→  if (regionalPopulationDecline > 0.30) {
   555→    // 30%+ REGIONAL population decline → revenue drops proportionally
   556→    // If 80% of local customers died, revenue drops 80%
   557→    const revenueLoss = Math.min(0.95, regionalPopulationDecline * 0.8); // Cap at 95% loss
   558→    baseRevenue *= (1 - revenueLoss);
   559→  }
   560→  
   561→  // 2. FOOD CRISIS PENALTY
   562→  // Starving people don't buy AI services
   563→  // Note: foodSecurity not in EnvironmentalAccumulation, use climate stability as proxy
   564→  const foodSecurity = state.environmentalAccumulation.climateStability;
   565→  if (foodSecurity < 0.4) {
   566→    const foodCrisisSeverity = (0.4 - foodSecurity) / 0.4; // 0-1 scale
   567→    baseRevenue *= (1 - foodCrisisSeverity * 0.5); // Up to 50% revenue loss
   568→  }
   569→  
   570→  // 3. INFRASTRUCTURE COLLAPSE PENALTY
   571→  // Cascading crises disrupt supply chains, power grids, internet
   572→  const env = state.environmentalAccumulation;
   573→  const crisisCount = [
   574→    env.resourceCrisisActive,
   575→    env.climateCrisisActive,
   576→    state.socialAccumulation.institutionalFailureActive,
   577→    state.socialAccumulation.socialUnrestActive,
   578→    state.technologicalRisk.controlLossActive
   579→  ].filter(Boolean).length;
   580→  
   581→  if (crisisCount >= 4) {
   582→    // 4+ active crises → infrastructure failing
   583→    const infrastructurePenalty = Math.min(0.70, (crisisCount - 3) * 0.20); // 20-70% loss
   584→    baseRevenue *= (1 - infrastructurePenalty);
   585→  }
   586→  
   587→  // 4. CASCADE COLLAPSE PENALTY
   588→  // During tipping point cascade, everything breaks down
   589→  if (state.planetaryBoundariesSystem.cascadeActive) {
   590→    const cascadeSeverity = state.planetaryBoundariesSystem.cascadeSeverity || 0;
   591→    baseRevenue *= (1 - cascadeSeverity * 0.40); // Up to 40% additional loss
   592→  }
   593→  
   594→  return Math.max(0, baseRevenue);
   595→}
