   597→/**
   598→ * Calculate revenue from selling unused compute capacity
   599→ * 
   600→ * IMPORTANT: Government doesn't sell capacity (they use it internally)
   601→ */
   602→export function calculateComputeRevenue(org: Organization, state: GameState): number {
   603→  // Government doesn't sell compute
   604→  if (org.type === 'government') return 0;
   605→  
   606→  // Calculate unused capacity
   607→  const ownedDCs = state.computeInfrastructure.dataCenters.filter(dc => 
   608→    org.ownedDataCenters.includes(dc.id) && dc.operational
   609→  );
   610→  
   611→  const totalCapacity = ownedDCs.reduce((sum, dc) => sum + dc.capacity * dc.efficiency, 0);
   612→  
   613→  // Handle computeAllocations as either Map or Object (after JSON serialization)
   614→  const allocations = state.computeInfrastructure.computeAllocations;
   615→  const allocationValues = allocations instanceof Map 
   616→    ? Array.from(allocations.values())
   617→    : Object.values(allocations);
   618→  
   619→  const allocatedCompute = allocationValues
   620→    .filter((alloc: any) => org.ownedAIModels.includes(alloc.aiId))
   621→    .reduce((sum: number, alloc: any) => sum + alloc.allocated, 0);
   622→  
   623→  const unusedCapacity = Math.max(0, totalCapacity - allocatedCompute);
   624→  
   625→  // Revenue: $2M per PetaFLOP of unused capacity per month
   626→  // Based on research: AWS/Azure charge ~$2-4/GPU-hour, 1 PFLOP ≈ 1000 GPUs
   627→  // 1 PFLOP × 720 hr/mo × $3/hr = ~$2.16M/month
   628→  const revenuePerPetaFLOP = 2.0;
   629→  
   630→  return unusedCapacity * revenuePerPetaFLOP;
   631→}
