   633→/**
   634→ * Phase 8: Collect revenue from AI services + compute sales
   635→ */
   636→export function collectRevenue(org: Organization, state: GameState): void {
   637→  // P0.2 FIX: Bankrupt organizations cannot generate revenue
   638→  // Check if organization is bankrupt (capital = 0, revenue = 0, no data centers)
   639→  if (org.capital === 0 && org.monthlyRevenue === 0 && org.ownedDataCenters.length === 0) {
   640→    // Organization is bankrupt - no revenue generation possible
   641→    return;
   642→  }
   643→
   644→  const aiRevenue = calculateAIRevenue(org, state);
   645→  const computeRevenue = calculateComputeRevenue(org, state);
   646→
   647→  const totalRevenue = aiRevenue + computeRevenue;
   648→
   649→  // Update monthly revenue (smoothly transition, don't jump suddenly)
   650→  org.monthlyRevenue = org.monthlyRevenue * 0.7 + totalRevenue * 0.3;
   651→
   652→  org.capital += org.monthlyRevenue;
   653→}
