   655→/**
   656→ * Calculate total monthly expenses
   657→ */
   658→export function calculateTotalExpenses(org: Organization, state: GameState): {
   659→  baseExpenses: number;
   660→  dcOperational: number;
   661→  projectCosts: number;
   662→  total: number;
   663→} {
   664→  // FIX (Oct 13, 2025 v2): Expenses as % of revenue (realistic business model)
   665→  // Real companies: 70-90% of revenue goes to expenses, 10-30% profit margin
   666→  // Expenses: payroll, R&D, facilities, marketing, legal, failed products, dividends
   667→  
   668→  // Get current monthly revenue
   669→  const monthlyRevenue = org.monthlyRevenue || 10; // Fallback to $10M
   670→  
   671→  // === PROFIT MARGIN BASED ON COMPANY STAGE ===
   672→  // Growth-stage (low capital): 10% margin (aggressive reinvestment)
   673→  // Mature (high capital): 25% margin (more conservative)
   674→  const isGrowthStage = org.capital < 500; // < $500M = still growing aggressively
   675→  const profitMargin = isGrowthStage ? 0.10 : 0.25;
   676→  
   677→  // Base expenses = (1 - margin) * revenue
   678→  // Example: $1000M revenue, 20% margin → $800M expenses, $200M profit
   679→  let baseExpenses = monthlyRevenue * (1 - profitMargin);
   680→  
   681→  // === EXPENSE BREAKDOWN (for realism, but we use aggregate) ===
   682→  // - Payroll: 40-50% of revenue (engineers, researchers, execs)
   683→  // - R&D: 15-25% (training models, safety research, experiments)
   684→  // - Infrastructure: 10-15% (data centers, cloud, facilities)
   685→  // - Sales/Marketing: 10-20% (customer acquisition)
   686→  // - Legal/Compliance: 2-5% (regulations, IP, lawsuits)
   687→  // - Failed products: 5-10% (not all bets pay off)
   688→  // - Shareholder returns: 5-10% (dividends, buybacks if profitable)
   689→  
   690→  // === DATA CENTER OPERATIONAL COSTS (additional) ===
   691→  let dcOperational = state.computeInfrastructure.dataCenters
   692→    .filter(dc => org.ownedDataCenters.includes(dc.id) && dc.operational)
   693→    .reduce((sum, dc) => sum + dc.operationalCost, 0);
   694→  
   695→  // === PROJECT COSTS (already paid, track for reporting) ===
   696→  const projectCosts = org.currentProjects.reduce((sum, project) => {
   697→    const duration = project.completionMonth - project.startMonth;
   698→    if (project.type === 'datacenter_construction') {
   699→      return sum + (project.capitalInvested * 0.7) / duration;
   700→    } else if (project.type === 'model_training') {
   701→      return sum + (project.capitalInvested * 0.5) / duration;
   702→    }
   703→    return sum;
   704→  }, 0);
   705→  
   706→  // === CRISIS EXPENSE MULTIPLIERS ===
   707→  // During collapse, costs spike (emergency operations, supply chain chaos)
   708→  const env = state.environmentalAccumulation;
   709→  const crisisCount = [
   710→    env.resourceCrisisActive,
   711→    env.climateCrisisActive,
   712→    state.socialAccumulation.institutionalFailureActive,
   713→    state.socialAccumulation.socialUnrestActive,
   714→    state.technologicalRisk.controlLossActive
   715→  ].filter(Boolean).length;
   716→  
   717→  if (crisisCount >= 4) {
   718→    // 4+ crises: +100% expenses (emergency mode, everything costs double)
   719→    baseExpenses *= 2.0;
   720→    dcOperational *= 1.5; // DC costs also spike
   721→  } else if (crisisCount >= 3) {
   722→    // 3 crises: +50% expenses
   723→    baseExpenses *= 1.5;
   724→    dcOperational *= 1.3;
   725→  } else if (crisisCount >= 2) {
   726→    // 2 crises: +20% expenses
   727→    baseExpenses *= 1.2;
   728→  }
   729→  
   730→  // === POPULATION COLLAPSE MULTIPLIER ===
   731→  // Workforce dying → hire replacements at premium, emergency contractors
   732→  const regionalPopulationDecline = calculateRegionalPopulationDecline(org, state);
   733→  if (regionalPopulationDecline > 0.50) {
   734→    // 50%+ workforce dead → 2-3x labor costs for survivors
   735→    const laborMultiplier = 1 + (regionalPopulationDecline * 2); // 1.0x → 3.0x
   736→    baseExpenses *= laborMultiplier;
   737→  }
   738→  
   739→  return {
   740→    baseExpenses,
   741→    dcOperational,
   742→    projectCosts,
   743→    total: baseExpenses + dcOperational // projectCosts already deducted
   744→  };
   745→}
   746→
   747→/**
   748→ * Phase 8: Pay all expenses
   749→ */
   750→export function payExpenses(org: Organization, state: GameState): void {
   751→  const expenses = calculateTotalExpenses(org, state);
   752→  
   753→  // Pay base expenses + DC operational costs
   754→  // (Project costs are already paid in updateProjects)
   755→  org.capital -= expenses.total;
   756→}
