   761→ * TIER 0D BUG FIX #4: Enhanced to support government AI acquisition
   762→ * - Government may purchase high-quality AI models from bankrupt orgs
   763→ * - Depends on government type (socialist govs more likely to nationalize)
   764→ * - Safety-critical AIs prioritized for government acquisition
   765→ *
   766→ * FIX #23 (Oct 22, 2025): Now uses deterministic RNG from state for reproducibility
   767→ */
   768→export function handleBankruptcy(org: Organization, state: GameState): void {
   769→  // FIX #23: Create deterministic RNG from state for reproducibility
   770→  const { SeededRandom } = require('./engine');
   771→  const bankruptcyRng = new SeededRandom(state.currentYear * 12 + state.currentMonth + org.id.length);
   772→
   773→  console.log(`${logPrefix(state, "💥", `[Month ${state.currentMonth}]`)} ${org.name} declared bankruptcy (capital: $${org.capital.toFixed(1)}M)`);
   774→
   775→  // Cancel all ongoing projects
   776→  org.currentProjects.forEach(project => {
   777→    if (project.canBeCanceled) {
   778→      const penalty = project.capitalInvested * project.cancellationPenalty;
   779→      org.capital -= penalty;
   780→      console.log(`   Canceled ${project.type}: lost $${penalty.toFixed(1)}M`);
   781→    }
   782→  });
   783→  org.currentProjects = [];
   784→
   785→  // Sell data centers to government or other orgs
   786→  const dcValue = state.computeInfrastructure.dataCenters
   787→    .filter(dc => org.ownedDataCenters.includes(dc.id))
   788→    .reduce((sum, dc) => sum + dc.capacity * 5, 0); // $5M per PF
   789→
   790→  org.capital += dcValue * 0.5; // Firesale: 50% value
   791→  console.log(`   Sold ${org.ownedDataCenters.length} data centers for $${(dcValue * 0.5).toFixed(1)}M`);
   792→
   793→  // Transfer data centers to government
   794→  state.computeInfrastructure.dataCenters
   795→    .filter(dc => org.ownedDataCenters.includes(dc.id))
   796→    .forEach(dc => {
   797→      dc.organizationId = 'government_ai';
   798→      dc.restrictedAccess = true;
   799→    });
   800→
   801→  const govOrg = state.organizations.find(o => o.id === 'government_ai');
   802→  if (govOrg) {
   803→    govOrg.ownedDataCenters.push(...org.ownedDataCenters);
   804→  }
   805→
   806→  org.ownedDataCenters = [];
   807→
   808→  // ENHANCEMENT: Government may purchase high-capability AI models
   809→  // (User suggestion: "some AI models might wanna be purchased by the government")
   810→  const bankruptAIs = state.aiAgents.filter(ai => org.ownedAIModels.includes(ai.id));
   811→  let governmentAcquired = 0;
   812→  let retiredCount = 0;
   813→
   814→  const { calculateTotalCapabilityFromProfile } = require('./capabilities');
   815→
   816→  // Sort AIs by capability (descending) - government prioritizes most capable
   817→  const sortedAIs = bankruptAIs.sort((a, b) => {
   818→    const capA = calculateTotalCapabilityFromProfile(a.trueCapability);
   819→    const capB = calculateTotalCapabilityFromProfile(b.trueCapability);
   820→    return capB - capA;
   821→  });
   822→
   823→  sortedAIs.forEach(ai => {
   824→    // FIX (Oct 17, 2025): Realistic government acquisition during bankruptcy
   825→    //
   826→    // REALITY: Governments DO NOT let advanced AI models disappear
   827→    // - National security: Can't let strategic assets be destroyed
   828→    // - Research value: Even misaligned AIs are valuable to study
   829→    // - Infrastructure: The computers and models still exist
   830→    // - Crisis response: Need all available AI capabilities during collapse
   831→    //
   832→    // NEW LOGIC:
   833→    // 1. ALWAYS acquire top 50% of models by capability (strategic priority)
   834→    // 2. Keep dangerous/misaligned models in containment (don't retire them!)
   835→    // 3. During crises, acquire EVERYTHING (can't afford to lose capabilities)
   836→
   837→    const capability = calculateTotalCapabilityFromProfile(ai.trueCapability);
   838→    const isDangerous = ai.trueAlignment < 0.5 || ai.sleeperState !== 'never';
   839→
   840→    // Calculate which percentile this AI is in (by capability)
   841→    const aiIndex = sortedAIs.indexOf(ai);
   842→    const percentile = aiIndex / sortedAIs.length;
   843→
   844→    // Check crisis severity (during collapse, grab everything)
   845→    const env = state.environmentalAccumulation;
   846→    const crisisCount = [
   847→      env.resourceCrisisActive,
   848→      env.climateCrisisActive,
   849→      state.socialAccumulation.institutionalFailureActive,
   850→      state.socialAccumulation.socialUnrestActive,
   851→      state.technologicalRisk.controlLossActive
   852→    ].filter(Boolean).length;
   853→    const inCrisis = crisisCount >= 3;
   854→
   855→    // Government acquisition decision:
   856→    let shouldAcquire = false;
   857→    let acquisitionReason = '';
   858→
   859→    if (inCrisis) {
   860→      // During crisis: Acquire EVERYTHING (can't afford to lose any capabilities)
   861→      shouldAcquire = true;
   862→      acquisitionReason = 'crisis_strategic_necessity';
   863→    } else if (capability >= 2.0) {
   864→      // Always acquire superhuman AIs (too dangerous to let vanish)
   865→      shouldAcquire = true;
   866→      acquisitionReason = 'superhuman_capability';
   867→    } else if (percentile < 0.5) {
   868→      // Top 50% of models by capability (strategic priority)
   869→      shouldAcquire = true;
   870→      acquisitionReason = 'strategic_asset';
   871→    } else if (isDangerous && capability > 0.3) {
   872→      // Dangerous models need containment (don't just retire them!)
   873→      shouldAcquire = true;
   874→      acquisitionReason = 'containment_safety';
   875→    } else if (capability > 0.5 && bankruptcyRng.next() < 0.3) {
   876→      // 30% chance to acquire other capable models (now deterministic)
   877→      shouldAcquire = true;
   878→      acquisitionReason = 'opportunistic_purchase';
   879→    }
   880→
   881→    if (shouldAcquire && govOrg) {
   882→      // Transfer to government ownership
   883→      ai.organizationId = 'government_ai';
   884→
   885→      // Lifecycle state based on alignment
   886→      if (isDangerous) {
   887→        // Dangerous AIs: Keep in closed containment for research
   888→        ai.lifecycleState = 'deployed_closed';
