    climateReparationsOwed: 0,
    climateReparationsReceived: 0,
    militaryEmissionsPercent: 0,
    climateReparationsWillingness: 0,
    climateMigrationPressure: 0,
    greenTechReceived: 0,
    greenTechShared: 0
  };
}

